require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';require_once __DIR__.'/app/lib/Entitlements.php';$pdo=Db::pdo();Security::start();$u=Security::user();if(!$u){header('Location:/login?next='.rawurlencode('/roi-tco'));exit;}$ctx=Entitlements::context($pdo,$u);$csrf=Security::csrf();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>ROI & TCO Model | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;background:#f6f8fb;color:#172033;margin:0}.wrap{max-width:1180px;margin:auto;padding:24px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:18px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.two{grid-template-columns:1fr 1fr}label{display:block;font-size:12px;font-weight:700;margin:8px 0 4px}input,select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cbd5e1;border-radius:8px}button{border:0;border-radius:8px;padding:10px 13px;background:#1A365D;color:#fff;font-weight:700;cursor:pointer}.secondary{background:#475569}.muted{color:#64748b}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric{background:#f8fafc;border-radius:10px;padding:12px}.metric b{font-size:22px;display:block}.warn{background:#fff7ed;padding:10px;border-radius:10px}.ok{background:#ecfdf5;padding:10px;border-radius:10px}.pill{display:inline-block;background:#eef2ff;border-radius:999px;padding:4px 8px;font-size:11px}@media(max-width:800px){.grid,.two,.metrics{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>ROI & TCO Model</h1><p class="muted">Model the financial case for a software decision. Verified pricing evidence is shown separately from buyer assumptions. Estimated savings are never presented as guaranteed outcomes.</p><div class="card"><div class="grid"><div><label>Selection project ID</label><input id="project_id" type="number"></div><div><label>Product ID (optional)</label><input id="product_id" type="number"></div><div><label>Business Case ID (optional)</label><input id="business_case_id" type="number"></div></div><div class="grid"><div><label>Title</label><input id="title" value="ROI/TCO Model"></div><div><label>Currency</label><input id="currency" value="USD" maxlength="3"></div><div><label>Horizon</label><select id="horizon_years"><option>1</option><option selected>3</option><option>5</option></select></div></div></div><div class="card"><h2>Buyer assumptions</h2><p class="muted">Leave unknown values blank. They will remain visible as unknown rather than being invented.</p><div id="fields" class="grid"></div><p><button onclick="preview()">Calculate preview</button> <?php if($ctx['features']['roi_tco_model']): ?><button class="secondary" onclick="saveModel()">Save Pro model</button><?php endif; ?></p><div id="status"></div></div><div class="card"><h2>Verified pricing reference</h2><div id="pricing" class="muted">No product selected yet.</div></div><div class="card"><h2>Results</h2><div id="metrics"></div><div id="unknown"></div></div><?php if($ctx['features']['roi_tco_model']): ?><div class="card"><h2>Scenario comparison</h2><div id="scenarios"></div><p class="muted">Conservative: +10% modeled costs / -25% modeled benefits. Optimistic: -5% modeled costs / +20% modeled benefits. These are sensitivity scenarios, not forecasts.</p></div><?php else: ?><div class="card warn">Registered accounts can calculate a temporary base preview. Pro saves models and adds multi-scenario analysis and Business Case linkage. <a href="/plans">View plans</a>.</div><?php endif; ?></main><script>
const csrf=<?=json_encode($csrf)?>,pro=<?=json_encode((bool)$ctx['features']['roi_tco_model'])?>;const defs=[['user_count','User/license count'],['subscription_annual','Annual subscription/license cost'],['implementation_cost','Implementation cost'],['migration_cost','Migration cost'],['integration_cost','Integration cost'],['training_change_cost','Training/change-management cost'],['infrastructure_annual','Annual infrastructure/hosting'],['support_maintenance_annual','Annual support/maintenance'],['internal_manpower_cost','Internal manpower effort cost'],['productivity_savings_annual','Annual productivity savings'],['avoided_legacy_cost_annual','Annual avoided legacy-system cost'],['revenue_uplift_annual','Annual revenue uplift'],['risk_reduction_annual','Annual risk/incident cost reduction']];document.getElementById('fields').innerHTML=defs.map(([k,l])=>`<div><label>${l}</label><input id="${k}" type="number" step="0.01" min="0"></div>`).join('');function assumptions(){let a={};defs.forEach(([k])=>a[k]=document.getElementById(k).value);return a}async function call(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':csrf};let r=await fetch(url,opt),d=await r.json().catch(()=>({error:'invalid_response'}));if(!r.ok)throw new Error(d.error||d.message||'request_failed');return d}function money(v){return v===null||v===undefined?'—':Number(v).toLocaleString(undefined,{maximumFractionDigits:2})}function render(d){let r=d.results||d;document.getElementById('metrics').innerHTML=`<div class="metrics"><div class="metric"><span>Year 1 cost</span><b>${money(r.year_1_cost)}</b></div><div class="metric"><span>${r.horizon_years}-year TCO</span><b>${money(r.tco)}</b></div><div class="metric"><span>ROI</span><b>${r.roi_percent===null?'—':r.roi_percent+'%'}</b></div><div class="metric"><span>Payback</span><b>${r.payback_months===null?'—':r.payback_months+' mo'}</b></div><div class="metric"><span>Annual benefit</span><b>${money(r.annual_benefit)}</b></div><div class="metric"><span>Net benefit</span><b>${money(r.net_benefit)}</b></div><div class="metric"><span>Cost/user/month</span><b>${money(r.cost_per_user_month)}</b></div><div class="metric"><span>Input completeness</span><b>${r.input_completeness_percent}%</b></div></div><p class="muted">${r.disclaimer}</p>`;document.getElementById('unknown').innerHTML=r.unknown_inputs?.length?`<div class="warn"><b>Unknown inputs:</b> ${r.unknown_inputs.join(', ')}</div>`:'<div class="ok">All modeled cost and benefit inputs are populated.</div>';if(d.verified_pricing){let p=d.verified_pricing;document.getElementById('pricing').innerHTML=`<b>${money(p.amount_min)}${p.amount_max!==null?' – '+money(p.amount_max):''} ${p.currency||''}</b> / ${p.billing_period||'period not recorded'}<br><span class="muted">${p.usage_note}</span>`}else document.getElementById('pricing').textContent='No verified pricing reference is available for this product.';if(d.scenarios){document.getElementById('scenarios').innerHTML='<div class="grid">'+Object.entries(d.scenarios).map(([k,x])=>`<div class="metric"><span class="pill">${k}</span><b>${x.roi_percent===null?'—':x.roi_percent+'% ROI'}</b><div>${money(x.tco)} TCO</div><div>${money(x.net_benefit)} net benefit</div></div>`).join('')+'</div>'}}
async function preview(){try{let d=await call('/api/roi-tco/preview',{method:'POST',body:JSON.stringify({project_id:+project_id.value,product_id:+product_id.value||null,horizon_years:+horizon_years.value,assumptions:assumptions()})});render(d);status.innerHTML='<div class="ok">Preview calculated. Nothing was saved.</div>'}catch(e){status.innerHTML='<div class="warn">'+e.message+'</div>'}}async function saveModel(){try{let d=await call('/api/roi-tco',{method:'POST',body:JSON.stringify({project_id:+project_id.value,product_id:+product_id.value||null,business_case_id:+business_case_id.value||null,title:title.value,currency:currency.value,horizon_years:+horizon_years.value,assumptions:assumptions()})});render(d);status.innerHTML='<div class="ok">Saved model #'+d.id+'.</div>'}catch(e){status.innerHTML='<div class="warn">'+e.message+'</div>'}}
</script></body></html>